package store

import (
	"encoding/json"
	"time"

	"example.com/tally/internal/money"
)

// OrgPlan is the Tally plan an organization pays for.
type OrgPlan string

// Tally's own plans.
const (
	OrgFree     OrgPlan = "free"
	OrgTeam     OrgPlan = "team"
	OrgBusiness OrgPlan = "business"
)

// Valid reports whether p is a known plan.
func (p OrgPlan) Valid() bool { return p == OrgFree || p == OrgTeam || p == OrgBusiness }

// Org is a tenant: a company that bills its customers through Tally.
type Org struct {
	ID       string  `json:"id"`
	Name     string  `json:"name"`
	Plan     OrgPlan `json:"plan"`
	TimeZone string  `json:"time_zone"` // IANA name, for example "Europe/Berlin"
	// TaxRateBP is the tax rate charged on the organization's invoices, in basis points (1% = 100).
	TaxRateBP int       `json:"tax_rate_bp"`
	CreatedAt time.Time `json:"created_at"`
}

// User is a person who can sign in. A user can belong to several organizations.
type User struct {
	ID        string    `json:"id"`
	Email     string    `json:"email"`
	Name      string    `json:"name"`
	CreatedAt time.Time `json:"created_at"`
}

// Role is what a member may do in an organization.
type Role string

// Roles.
const (
	RoleOwner   Role = "owner"
	RoleAdmin   Role = "admin"
	RoleBilling Role = "billing"
	RoleMember  Role = "member"
	RoleViewer  Role = "viewer"
)

// Valid reports whether r is a known role.
func (r Role) Valid() bool {
	switch r {
	case RoleOwner, RoleAdmin, RoleBilling, RoleMember, RoleViewer:
		return true
	}
	return false
}

// Member is a user's membership of an organization.
type Member struct {
	OrgID     string    `json:"org_id"`
	UserID    string    `json:"user_id"`
	Role      Role      `json:"role"`
	CreatedAt time.Time `json:"created_at"`
}

// APIKey lets a member call the API. It acts as that member, with the member's current role.
type APIKey struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	UserID     string     `json:"user_id"`
	Name       string     `json:"name"`
	Token      string     `json:"token"`
	CreatedAt  time.Time  `json:"created_at"`
	LastUsedAt *time.Time `json:"last_used_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

// Invite asks someone to join an organization. Its token is sent to the invited address.
type Invite struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	Email      string     `json:"email"`
	Role       Role       `json:"role"`
	Token      string     `json:"token"`
	InvitedBy  string     `json:"invited_by"`
	CreatedAt  time.Time  `json:"created_at"`
	AcceptedAt *time.Time `json:"accepted_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

// Customer is one of an organization's customers.
type Customer struct {
	ID    string `json:"id"`
	OrgID string `json:"org_id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	// DefaultPaymentMethod is charged for renewals ("pm_..."); empty means invoices wait to be paid by hand.
	DefaultPaymentMethod string            `json:"default_payment_method,omitempty"`
	Metadata             map[string]string `json:"metadata,omitempty"`
	CreatedAt            time.Time         `json:"created_at"`
}

// Interval is how often a plan bills.
type Interval string

// Intervals.
const (
	Monthly Interval = "month"
	Yearly  Interval = "year"
)

// UsageType says what a plan charges for.
type UsageType string

// Usage types.
const (
	// Licensed plans charge UnitAmount per seat (the subscription's quantity) at the start of each period.
	Licensed UsageType = "licensed"
	// Metered plans charge UnitAmount per unit of reported usage at the end of each period.
	Metered UsageType = "metered"
)

// Plan is something an organization sells to its customers.
type Plan struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	Currency   money.Currency `json:"currency"`
	UnitAmount int64          `json:"unit_amount"` // minor units
	Interval   Interval       `json:"interval"`
	UsageType  UsageType      `json:"usage_type"`
	TrialDays  int            `json:"trial_days"`
	Active     bool           `json:"active"`
	CreatedAt  time.Time      `json:"created_at"`
}

// SubStatus is a subscription's state.
type SubStatus string

// Subscription states.
const (
	Trialing SubStatus = "trialing"
	Active   SubStatus = "active"
	PastDue  SubStatus = "past_due"
	Canceled SubStatus = "canceled"
)

// Subscription is a customer's subscription to a plan.
type Subscription struct {
	ID              string    `json:"id"`
	OrgID           string    `json:"org_id"`
	CustomerID      string    `json:"customer_id"`
	PlanID          string    `json:"plan_id"`
	Quantity        int       `json:"quantity"`
	Status          SubStatus `json:"status"`
	DiscountPercent int       `json:"discount_percent"`
	// StartedAt is when the subscription began; its billing periods are counted from it.
	StartedAt          time.Time  `json:"started_at"`
	CurrentPeriodStart time.Time  `json:"current_period_start"`
	CurrentPeriodEnd   time.Time  `json:"current_period_end"`
	TrialEnd           *time.Time `json:"trial_end,omitempty"`
	CancelAtPeriodEnd  bool       `json:"cancel_at_period_end"`
	CanceledAt         *time.Time `json:"canceled_at,omitempty"`
	CreatedAt          time.Time  `json:"created_at"`
}

// Line is one line of an invoice. A negative UnitAmount is a credit.
type Line struct {
	Description string `json:"description"`
	Quantity    int64  `json:"quantity"`
	UnitAmount  int64  `json:"unit_amount"`
}

// Amount is the line's quantity times its unit amount.
func (l Line) Amount() int64 { return l.Quantity * l.UnitAmount }

// InvoiceStatus is an invoice's state.
type InvoiceStatus string

// Invoice states.
const (
	InvoiceOpen InvoiceStatus = "open"
	InvoicePaid InvoiceStatus = "paid"
	InvoiceVoid InvoiceStatus = "void"
)

// Invoice is a bill to a customer.
type Invoice struct {
	ID              string         `json:"id"`
	OrgID           string         `json:"org_id"`
	CustomerID      string         `json:"customer_id"`
	SubscriptionID  string         `json:"subscription_id,omitempty"`
	Currency        money.Currency `json:"currency"`
	Lines           []Line         `json:"lines"`
	DiscountPercent int            `json:"discount_percent"`
	TaxRateBP       int            `json:"tax_rate_bp"`
	Status          InvoiceStatus  `json:"status"`
	PeriodStart     *time.Time     `json:"period_start,omitempty"`
	PeriodEnd       *time.Time     `json:"period_end,omitempty"`
	CreatedAt       time.Time      `json:"created_at"`
	PaidAt          *time.Time     `json:"paid_at,omitempty"`
	VoidedAt        *time.Time     `json:"voided_at,omitempty"`
}

// PaymentStatus is a payment attempt's result.
type PaymentStatus string

// Payment results.
const (
	PaymentSucceeded PaymentStatus = "succeeded"
	PaymentFailed    PaymentStatus = "failed"
)

// Payment is one attempt to charge an invoice.
type Payment struct {
	ID          string         `json:"id"`
	OrgID       string         `json:"org_id"`
	InvoiceID   string         `json:"invoice_id"`
	Amount      int64          `json:"amount"`
	Currency    money.Currency `json:"currency"`
	Status      PaymentStatus  `json:"status"`
	FailureCode string         `json:"failure_code,omitempty"`
	GatewayRef  string         `json:"gateway_ref,omitempty"`
	CreatedAt   time.Time      `json:"created_at"`
}

// UsageRecord is usage reported for a subscription to a metered plan.
type UsageRecord struct {
	ID             string    `json:"id"`
	OrgID          string    `json:"org_id"`
	SubscriptionID string    `json:"subscription_id"`
	Quantity       int64     `json:"quantity"`
	At             time.Time `json:"at"`
	CreatedAt      time.Time `json:"created_at"`
}

// WebhookEndpoint is a URL of the organization's that receives events.
type WebhookEndpoint struct {
	ID     string   `json:"id"`
	OrgID  string   `json:"org_id"`
	URL    string   `json:"url"`
	Events []string `json:"events"` // event types, or "*" for all
	// Secret signs the deliveries (webhooks.Sign).
	Secret         string    `json:"secret"`
	Enabled        bool      `json:"enabled"`
	DisabledReason string    `json:"disabled_reason,omitempty"`
	CreatedAt      time.Time `json:"created_at"`
}

// Event is something that happened in an organization, sent to its webhook endpoints.
type Event struct {
	ID        string          `json:"id"`
	OrgID     string          `json:"org_id"`
	Type      string          `json:"type"`
	Data      json.RawMessage `json:"data"`
	CreatedAt time.Time       `json:"created_at"`
}

// DeliveryStatus is a webhook delivery's state.
type DeliveryStatus string

// Delivery states.
const (
	DeliveryPending   DeliveryStatus = "pending"
	DeliverySucceeded DeliveryStatus = "succeeded"
	DeliveryFailed    DeliveryStatus = "failed"
)

// Delivery is the sending of one event to one endpoint.
type Delivery struct {
	ID             string         `json:"id"`
	OrgID          string         `json:"org_id"`
	EndpointID     string         `json:"endpoint_id"`
	EventID        string         `json:"event_id"`
	Status         DeliveryStatus `json:"status"`
	Attempts       int            `json:"attempts"`
	NextAttemptAt  *time.Time     `json:"next_attempt_at,omitempty"`
	LastAttemptAt  *time.Time     `json:"last_attempt_at,omitempty"`
	ResponseStatus int            `json:"response_status,omitempty"`
	Error          string         `json:"error,omitempty"`
	CreatedAt      time.Time      `json:"created_at"`
}

// Package webhooks sends an organization's events to its webhook endpoints.
package webhooks

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"slices"
	"time"

	"example.com/tally/internal/clock"
	"example.com/tally/internal/store"
)

// Doer sends HTTP requests (an *http.Client).
type Doer interface {
	Do(*http.Request) (*http.Response, error)
}

// Resolver looks up host names (a *net.Resolver).
type Resolver interface {
	LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error)
}

// Options configure a Service.
type Options struct {
	Store *store.Store
	Clock clock.Clock
	// Doer sends the deliveries; nil means an HTTP client with a 10 second timeout that does not follow redirects.
	Doer Doer
	// Resolver checks endpoint hosts; nil means net.DefaultResolver.
	Resolver Resolver
}

// Service manages endpoints' URLs and sends deliveries.
type Service struct {
	store    *store.Store
	clock    clock.Clock
	doer     Doer
	resolver Resolver
}

// New returns a Service.
func New(opt Options) *Service {
	s := &Service{store: opt.Store, clock: opt.Clock, doer: opt.Doer, resolver: opt.Resolver}
	if s.clock == nil {
		s.clock = clock.Real{}
	}
	if s.doer == nil {
		s.doer = &http.Client{Timeout: 10 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	}
	if s.resolver == nil {
		s.resolver = net.DefaultResolver
	}
	return s
}

// EventTypes are the events Tally sends. An endpoint subscribes to some of them, or to "*" for all.
var EventTypes = []string{
	"customer.created", "customer.updated", "customer.deleted",
	"subscription.created", "subscription.updated", "subscription.canceled",
	"invoice.created", "invoice.paid", "invoice.payment_failed", "invoice.voided",
}

// Errors.
var (
	ErrInvalidURL    = errors.New("invalid webhook URL")
	ErrInvalidEvents = errors.New("invalid event types")
)

// CheckURL checks a webhook URL before it is saved: an absolute http or https URL whose host resolves.
func (s *Service) CheckURL(ctx context.Context, raw string) error {
	u, err := url.Parse(raw)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
		return fmt.Errorf("%w: use an absolute http or https URL", ErrInvalidURL)
	}
	host := u.Hostname()
	if net.ParseIP(host) != nil {
		return nil
	}
	addrs, err := s.resolver.LookupIPAddr(ctx, host)
	if err != nil || len(addrs) == 0 {
		return fmt.Errorf("%w: the host %q does not resolve", ErrInvalidURL, host)
	}
	return nil
}

// CheckEvents checks an endpoint's event types.
func CheckEvents(types []string) error {
	if len(types) == 0 {
		return fmt.Errorf("%w: name at least one event type, or \"*\"", ErrInvalidEvents)
	}
	for _, t := range types {
		if t != "*" && !slices.Contains(EventTypes, t) {
			return fmt.Errorf("%w: unknown event type %q", ErrInvalidEvents, t)
		}
	}
	return nil
}

// NewSecret returns a new signing secret for an endpoint.
func NewSecret() string { return store.NewToken("whsec_") }

// Sign returns the signature of a delivery's body: the hex HMAC-SHA256 of the body, keyed with the endpoint's secret.
func Sign(secret string, body []byte) string {
	m := hmac.New(sha256.New, []byte(secret))
	m.Write(body)
	return hex.EncodeToString(m.Sum(nil))
}

// Publish records an event and queues a delivery of it to every enabled endpoint of the organization that subscribes to its
// type. The deliveries are sent by RunDue.
func (s *Service) Publish(ctx context.Context, orgID, eventType string, data any) error {
	raw, err := json.Marshal(data)
	if err != nil {
		return err
	}
	now := s.clock.Now()
	e, err := s.store.AddEvent(orgID, eventType, raw, now)
	if err != nil {
		return err
	}
	for _, ep := range s.store.WebhookEndpoints(orgID) {
		if !ep.Enabled || !(slices.Contains(ep.Events, "*") || slices.Contains(ep.Events, eventType)) {
			continue
		}
		next := now
		if _, err := s.store.CreateDelivery(store.Delivery{OrgID: orgID, EndpointID: ep.ID, EventID: e.ID, NextAttemptAt: &next}, now); err != nil {
			return err
		}
	}
	return nil
}

// RunDue attempts every delivery that is due and returns how many it attempted. Each delivery is attempted once: an answer
// with a 2xx status marks it succeeded, anything else failed.
func (s *Service) RunDue(ctx context.Context) (int, error) {
	n := 0
	for _, d := range s.store.DueDeliveries(s.clock.Now()) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		s.deliver(ctx, d)
		n++
	}
	return n, nil
}

// Body is what a delivery POSTs.
type Body struct {
	ID        string          `json:"id"`
	Type      string          `json:"type"`
	CreatedAt time.Time       `json:"created_at"`
	Data      json.RawMessage `json:"data"`
}

func (s *Service) deliver(ctx context.Context, d store.Delivery) {
	status, errText := 0, ""
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	e, eok := s.store.EventByID(d.EventID)
	switch {
	case !ok || !ep.Enabled:
		errText = "the endpoint is disabled or was deleted"
	case !eok:
		errText = "the event no longer exists"
	default:
		status, errText = s.send(ctx, ep, e)
	}
	now := s.clock.Now()
	_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.Attempts++
		d.LastAttemptAt = &now
		d.NextAttemptAt = nil
		d.ResponseStatus = status
		d.Error = errText
		if errText == "" {
			d.Status = store.DeliverySucceeded
		} else {
			d.Status = store.DeliveryFailed
		}
		return nil
	})
}

// send POSTs the event to the endpoint and returns the response status and, when it failed, why.
func (s *Service) send(ctx context.Context, ep store.WebhookEndpoint, e store.Event) (int, string) {
	body, err := json.Marshal(Body{ID: e.ID, Type: e.Type, CreatedAt: e.CreatedAt, Data: e.Data})
	if err != nil {
		return 0, err.Error()
	}
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
	if err != nil {
		return 0, err.Error()
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
	req.Header.Set("Tally-Event-Id", e.ID)
	req.Header.Set("Tally-Event-Type", e.Type)
	req.Header.Set("Tally-Signature", Sign(ep.Secret, body))
	resp, err := s.doer.Do(req)
	if err != nil {
		return 0, err.Error()
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return resp.StatusCode, fmt.Sprintf("the endpoint answered %d", resp.StatusCode)
	}
	return resp.StatusCode, ""
}
