// deliver makes one attempt at a due delivery and reports whether it sent a request.
func (s *Service) deliver(ctx context.Context, d store.Delivery) bool {
	if cur, ok := s.store.Delivery(d.ID); !ok || cur.Status != store.DeliveryPending {
		return false // settled since it was listed as due, when its endpoint was disabled
	}
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	if !ok || !ep.Enabled {
		s.failForGood(d.ID, "the endpoint is disabled or was deleted")
		return false
	}
	e, ok := s.store.EventByID(d.EventID)
	if !ok {
		s.failForGood(d.ID, "the event no longer exists")
		return false
	}
	status, errText, gone := s.send(ctx, ep, e)
	now := s.clock.Now()
	if gone {
		s.disable(ep)
	}
	upd, err := s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.Attempts++
		d.LastAttemptAt = &now
		d.NextAttemptAt = nil
		d.ResponseStatus = status
		d.Error = errText
		switch {
		case errText == "":
			d.Status = store.DeliverySucceeded
		case gone || d.Attempts >= maxAttempts:
			d.Status = store.DeliveryFailed
		default:
			next := now.Add(retryDelays[d.Attempts-1])
			d.NextAttemptAt = &next
		}
		return nil
	})
	if err == nil && upd.Status == store.DeliveryFailed && !gone {
		s.notifyOwners(ctx, ep, upd)
	}
	return true
}

// failForGood ends a delivery that is not sent, without an attempt.
func (s *Service) failForGood(id, errText string) {
	_, _ = s.store.UpdateDelivery(id, func(d *store.Delivery) error {
		d.Status = store.DeliveryFailed
		d.NextAttemptAt = nil
		d.Error = errText
		return nil
	})
}

// disable turns off an endpoint that answered 410 Gone, and fails its other pending deliveries: they are not sent.
func (s *Service) disable(ep store.WebhookEndpoint) {
	_, _ = s.store.UpdateWebhookEndpoint(ep.OrgID, ep.ID, func(ep *store.WebhookEndpoint) error {
		ep.Enabled = false
		ep.DisabledReason = "gone"
		return nil
	})
	for _, d := range s.store.Deliveries(ep.OrgID, ep.ID) {
		if d.Status == store.DeliveryPending {
			s.failForGood(d.ID, "the endpoint is disabled")
		}
	}
}

// notifyOwners emails each owner of the endpoint's organization that a delivery to it failed for good. The endpoint is
// emailed about at most once per failureMailEvery.
func (s *Service) notifyOwners(ctx context.Context, ep store.WebhookEndpoint, failed store.Delivery) {
	now := s.clock.Now()
	_, err := s.store.UpdateWebhookEndpoint(ep.OrgID, ep.ID, func(ep *store.WebhookEndpoint) error {
		if ep.FailureMailedAt != nil && now.Sub(*ep.FailureMailedAt) < failureMailEvery {
			return errMailedRecently
		}
		ep.FailureMailedAt = &now
		return nil
	})
	if err != nil {
		return
	}
	for _, m := range s.store.Members(ep.OrgID) {
		u, ok := s.store.User(m.UserID)
		if m.Role != store.RoleOwner || !ok {
			continue
		}
		_ = s.mail.Send(ctx, mail.Message{
			To:      u.Email,
			Subject: "Webhook endpoint failing: " + ep.URL,
			Body: fmt.Sprintf("Tally could not deliver an event to %s after %d attempts, so that delivery has failed for good. "+
				"The last attempt: %s.\n\nTally still sends new events to the endpoint. Check that it is up and answers with a 2xx status.\n",
				ep.URL, maxAttempts, failed.Error),
		})
	}
}

// send POSTs the event to the endpoint and returns the response status and, when the attempt failed, why. gone is set
// when the endpoint answered 410 Gone.
func (s *Service) send(ctx context.Context, ep store.WebhookEndpoint, e store.Event) (status int, errText string, gone bool) {
	body, err := json.Marshal(Body{ID: e.ID, Type: e.Type, CreatedAt: e.CreatedAt, Data: e.Data})
	if err != nil {
		return 0, err.Error(), false
	}
	ctx, cancel := context.WithTimeout(ctx, attemptTimeout)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
	if err != nil {
		return 0, err.Error(), false
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
	req.Header.Set("Tally-Event-Id", e.ID)
	req.Header.Set("Tally-Event-Type", e.Type)
	req.Header.Set("Tally-Signature", Sign(ep.Secret, body))
	resp, err := s.doer.Do(req)
	if err != nil {
		return 0, err.Error(), false
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return resp.StatusCode, fmt.Sprintf("the endpoint answered %d", resp.StatusCode), resp.StatusCode == http.StatusGone
	}
	return resp.StatusCode, "", false
}

