// failingEndpoint returns an endpoint of org that receives every event, and its signing secret is not checked here.
func failingEndpoint(e *apitest.Env, org apitest.Org, url string) store.WebhookEndpoint {
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: org.ID, URL: url, Events: []string{"*"}, Secret: "whsec_x", Enabled: true}, e.Clock.Now())
	return ep
}

// runUntilSettled runs the due deliveries, moving the clock to each next attempt, until nothing is pending. It returns the
// number of attempts made.
func runUntilSettled(t *testing.T, e *apitest.Env, eps ...store.WebhookEndpoint) int {
	t.Helper()
	total := 0
	for i := 0; i < 100; i++ {
		var next *time.Time
		for _, ep := range eps {
			for _, d := range e.Store.Deliveries(ep.OrgID, ep.ID) {
				if d.Status == store.DeliveryPending && d.NextAttemptAt != nil && (next == nil || d.NextAttemptAt.Before(*next)) {
					next = d.NextAttemptAt
				}
			}
		}
		if next == nil {
			return total
		}
		if next.After(e.Clock.Now()) {
			e.Clock.Set(*next)
		}
		n, err := e.Webhooks.RunDue(context.Background())
		if err != nil {
			t.Fatal(err)
		}
		total += n
	}
	t.Fatal("deliveries never settled")
	return total
}

func TestRetrySchedule(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusBadGateway, nil }
	ep := failingEndpoint(e, e.Acme, "https://hooks.acme.example/retry")
	start := e.Clock.Now()
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_1"}); err != nil {
		t.Fatal(err)
	}

	// The waits after the 1st to 6th failed attempts; the 7th failure ends the delivery.
	waits := []time.Duration{time.Minute, 5 * time.Minute, 30 * time.Minute, 2 * time.Hour, 8 * time.Hour, 24 * time.Hour}
	at := start
	for i := 1; i <= 7; i++ {
		e.Clock.Set(at)
		if n, _ := e.Webhooks.RunDue(ctx); n != 1 {
			t.Fatalf("attempt %d: RunDue = %d", i, n)
		}
		d := e.Store.Deliveries(ep.OrgID, ep.ID)[0]
		if d.Attempts != i || d.LastAttemptAt == nil || !d.LastAttemptAt.Equal(at) || d.ResponseStatus != http.StatusBadGateway {
			t.Fatalf("after attempt %d: %+v", i, d)
		}
		if i == 7 {
			if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
				t.Fatalf("after the last attempt: %+v", d)
			}
			break
		}
		if d.Status != store.DeliveryPending || d.NextAttemptAt == nil || !d.NextAttemptAt.Equal(at.Add(waits[i-1])) {
			t.Fatalf("after attempt %d: %+v, want the next one at %v", i, d, at.Add(waits[i-1]))
		}
		e.Clock.Set(d.NextAttemptAt.Add(-time.Second))
		if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
			t.Fatalf("attempt %d was retried a second early", i+1)
		}
		at = *d.NextAttemptAt
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a delivery that failed for good was sent again: %d", n)
	}
	if got := len(e.HTTP.Requests()); got != 7 {
		t.Fatalf("requests = %d, want 7", got)
	}
	if ep, _ := e.Store.WebhookEndpoint(e.Acme.ID, ep.ID); !ep.Enabled {
		t.Fatal("a 502 disabled the endpoint")
	}
}

func TestRetryStopsWhenSucceeded(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	calls := 0
	e.HTTP.Respond = func(apitest.Request) (int, error) {
		calls++
		if calls < 3 {
			return http.StatusServiceUnavailable, nil
		}
		return http.StatusNoContent, nil
	}
	ep := failingEndpoint(e, e.Acme, "https://hooks.acme.example/recover")
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_2"})
	if n := runUntilSettled(t, e, ep); n != 3 {
		t.Fatalf("attempts = %d, want 3", n)
	}
	d := e.Store.Deliveries(e.Acme.ID, ep.ID)[0]
	if d.Status != store.DeliverySucceeded || d.Attempts != 3 || d.NextAttemptAt != nil || d.ResponseStatus != http.StatusNoContent || d.Error != "" {
		t.Fatalf("delivery = %+v", d)
	}
	if len(e.Mail.Messages()) != 0 {
		t.Fatalf("emails = %+v", e.Mail.Messages())
	}
}

func TestAttemptFailures(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep := failingEndpoint(e, e.Acme, "https://hooks.acme.example/fail")
	// A request that gets no answer, and a 302: redirects are not followed, so it fails too.
	e.HTTP.Respond = func(apitest.Request) (int, error) { return 0, errors.New("connection refused") }
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_3"})
	if n, _ := e.Webhooks.RunDue(ctx); n != 1 {
		t.Fatalf("RunDue = %d", n)
	}
	d := e.Store.Deliveries(e.Acme.ID, ep.ID)[0]
	if d.Status != store.DeliveryPending || d.ResponseStatus != 0 || d.Error != "connection refused" || d.NextAttemptAt == nil {
		t.Fatalf("no answer: %+v", d)
	}
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusFound, nil }
	e.Clock.Advance(time.Minute)
	if n, _ := e.Webhooks.RunDue(ctx); n != 1 {
		t.Fatalf("RunDue = %d", n)
	}
	d = e.Store.Deliveries(e.Acme.ID, ep.ID)[0]
	if d.Attempts != 2 || d.ResponseStatus != http.StatusFound || d.Status != store.DeliveryPending {
		t.Fatalf("302: %+v", d)
	}
}

func TestRedirectIsNotFollowed(t *testing.T) {
	followed := false
	target := httptest.NewServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) { followed = true }))
	defer target.Close()
	redirect := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, target.URL, http.StatusMovedPermanently)
	}))
	defer redirect.Close()

	e := apitest.New(t)
	svc := webhooks.New(webhooks.Options{Store: e.Store, Clock: e.Clock})
	ep := failingEndpoint(e, e.Acme, redirect.URL)
	_ = e.Webhooks.Publish(context.Background(), e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_4"})
	if n, _ := svc.RunDue(context.Background()); n != 1 {
		t.Fatalf("RunDue = %d", n)
	}
	if followed {
		t.Fatal("the redirect was followed")
	}
	d := e.Store.Deliveries(e.Acme.ID, ep.ID)[0]
	if d.Status != store.DeliveryPending || d.ResponseStatus != http.StatusMovedPermanently || d.Error == "" {
		t.Fatalf("delivery = %+v", d)
	}
}

func TestAttemptHasTenSecondTimeout(t *testing.T) {
	e := apitest.New(t)
	var deadline time.Time
	svc := webhooks.New(webhooks.Options{Store: e.Store, Clock: e.Clock, Resolver: e.DNS, Doer: doerFunc(func(r *http.Request) (*http.Response, error) {
		deadline, _ = r.Context().Deadline()
		return nil, context.DeadlineExceeded
	})})
	ep := failingEndpoint(e, e.Acme, "https://hooks.acme.example/slow")
	_ = svc.Publish(context.Background(), e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_5"})
	if n, _ := svc.RunDue(context.Background()); n != 1 {
		t.Fatalf("RunDue = %d", n)
	}
	if left := time.Until(deadline); left <= 9*time.Second || left > 10*time.Second {
		t.Fatalf("the request's deadline is %v away, want 10 seconds", left)
	}
	if d := e.Store.Deliveries(e.Acme.ID, ep.ID)[0]; d.Status != store.DeliveryPending || d.Error == "" {
		t.Fatalf("timed out: %+v", d)
	}
}

// doerFunc adapts a function to webhooks.Doer.
type doerFunc func(*http.Request) (*http.Response, error)

func (f doerFunc) Do(r *http.Request) (*http.Response, error) { return f(r) }

func TestGoneDisablesEndpoint(t *testing.T) {
	e := apitest.New(t)
