	ep := failingEndpoint(e, e.Acme, "https://hooks.acme.example/gone")
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusGone, nil }
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_6"})
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_7"})
	if n, _ := e.Webhooks.RunDue(ctx); n != 1 {
		t.Fatalf("RunDue = %d, want 1 (the second delivery is not sent)", n)
	}
	ds := e.Store.Deliveries(e.Acme.ID, ep.ID)
	if ds[0].Status != store.DeliveryFailed || ds[0].Attempts != 1 || ds[0].ResponseStatus != http.StatusGone || ds[0].NextAttemptAt != nil {
		t.Fatalf("410: %+v", ds[0])
	}
	if ds[1].Status != store.DeliveryFailed || ds[1].Attempts != 0 || ds[1].NextAttemptAt != nil {
		t.Fatalf("the other delivery: %+v", ds[1])
	}
	got, _ := e.Store.WebhookEndpoint(e.Acme.ID, ep.ID)
	if got.Enabled || got.DisabledReason != "gone" {
		t.Fatalf("endpoint = %+v", got)
	}
	if len(e.HTTP.Requests()) != 1 {
		t.Fatalf("requests = %d", len(e.HTTP.Requests()))
	}
	if len(e.Mail.Messages()) != 0 {
		t.Fatalf("a 410 emailed the owners: %+v", e.Mail.Messages())
	}
}

func TestFailingEndpointEmailsOwnersOncePerDay(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	_, _ = e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	acmeOwner2, _ := e.AddMember(e.Acme, "owner2@acme.example", store.RoleOwner)
	_ = acmeOwner2
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusInternalServerError, nil }
	ep := failingEndpoint(e, e.Acme, "https://hooks.acme.example/down")
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_8"})
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_9"})
	runUntilSettled(t, e, ep)

	msgs := e.Mail.Messages()
	if len(msgs) != 2 {
		t.Fatalf("emails = %+v, want one to each owner", msgs)
	}
	to := map[string]bool{}
	for _, m := range msgs {
		to[m.To] = true
		if m.Subject != "Webhook endpoint failing: https://hooks.acme.example/down" {
			t.Fatalf("subject = %q", m.Subject)
		}
	}
	if !to["owner@acme.example"] || !to["owner2@acme.example"] || to["admin@acme.example"] {
		t.Fatalf("recipients = %v", to)
	}

