// failingEndpoint returns an endpoint of org that receives every event, and its signing secret is not checked here.
func failingEndpoint(e *apitest.Env, org apitest.Org, url string) store.WebhookEndpoint {
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: org.ID, URL: url, Events: []string{"*"}, Secret: "whsec_x", Enabled: true}, e.Clock.Now())
	return ep
}

// runUntilSettled runs the due deliveries, moving the clock to each next attempt, until nothing is pending. It returns the
// number of attempts made.
func runUntilSettled(t *testing.T, e *apitest.Env, eps ...store.WebhookEndpoint) int {
	t.Helper()
	total := 0
	for i := 0; i < 100; i++ {
		var next *time.Time
		for _, ep := range eps {
			for _, d := range e.Store.Deliveries(ep.OrgID, ep.ID) {
				if d.Status == store.DeliveryPending && d.NextAttemptAt != nil && (next == nil || d.NextAttemptAt.Before(*next)) {
					next = d.NextAttemptAt
				}
			}
		}
		if next == nil {
			return total
		}
		if next.After(e.Clock.Now()) {
			e.Clock.Set(*next)
		}
		n, err := e.Webhooks.RunDue(context.Background())
		if err != nil {
			t.Fatal(err)
		}
		total += n
	}
	t.Fatal("deliveries never settled")
	return total
}

func TestRetrySchedule(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusBadGateway, nil }
	ep := failingEndpoint(e, e.Acme, "https://hooks.acme.example/retry")
	start := e.Clock.Now()
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_1"}); err != nil {
		t.Fatal(err)
	}

	// The waits after the 1st to 6th failed attempts; the 7th failure ends the delivery.
	waits := []time.Duration{time.Minute, 5 * time.Minute, 30 * time.Minute, 2 * time.Hour, 8 * time.Hour, 24 * time.Hour}
	at := start
	for i := 1; i <= 7; i++ {
		e.Clock.Set(at)
		if n, _ := e.Webhooks.RunDue(ctx); n != 1 {
			t.Fatalf("attempt %d: RunDue = %d", i, n)
		}
		d := e.Store.Deliveries(ep.OrgID, ep.ID)[0]
		if d.Attempts != i || d.LastAttemptAt == nil || !d.LastAttemptAt.Equal(at) || d.ResponseStatus != http.StatusBadGateway {
			t.Fatalf("after attempt %d: %+v", i, d)
		}
		if i == 7 {
			if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
				t.Fatalf("after the last attempt: %+v", d)
			}
			break
		}
		if d.Status != store.DeliveryPending || d.NextAttemptAt == nil || !d.NextAttemptAt.Equal(at.Add(waits[i-1])) {
			t.Fatalf("after attempt %d: %+v, want the next one at %v", i, d, at.Add(waits[i-1]))
		}
		e.Clock.Set(d.NextAttemptAt.Add(-time.Second))
		if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
			t.Fatalf("attempt %d was retried a second early", i+1)
		}
		at = *d.NextAttemptAt
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a delivery that failed for good was sent again: %d", n)
	}
	if got := len(e.HTTP.Requests()); got != 7 {
		t.Fatalf("requests = %d, want 7", got)
	}
	if ep, _ := e.Store.WebhookEndpoint(e.Acme.ID, ep.ID); !ep.Enabled {
		t.Fatal("a 502 disabled the endpoint")
	}
}

