func TestAttemptFailures(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep := failingEndpoint(e, e.Acme, "https://hooks.acme.example/fail")
	// A request that gets no answer, and a 302: redirects are not followed, so it fails too.
	e.HTTP.Respond = func(apitest.Request) (int, error) { return 0, errors.New("connection refused") }
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_3"})
	if n, _ := e.Webhooks.RunDue(ctx); n != 1 {
		t.Fatalf("RunDue = %d", n)
	}
	d := e.Store.Deliveries(e.Acme.ID, ep.ID)[0]
	if d.Status != store.DeliveryPending || d.ResponseStatus != 0 || d.Error != "connection refused" || d.NextAttemptAt == nil {
		t.Fatalf("no answer: %+v", d)
	}
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusFound, nil }
	e.Clock.Advance(time.Minute)
	if n, _ := e.Webhooks.RunDue(ctx); n != 1 {
		t.Fatalf("RunDue = %d", n)
	}
	d = e.Store.Deliveries(e.Acme.ID, ep.ID)[0]
	if d.Attempts != 2 || d.ResponseStatus != http.StatusFound || d.Status != store.DeliveryPending {
		t.Fatalf("302: %+v", d)
	}
}

func TestRedirectIsNotFollowed(t *testing.T) {
	followed := false
	target := httptest.NewServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) { followed = true }))
	defer target.Close()
	redirect := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, target.URL, http.StatusMovedPermanently)
	}))
	defer redirect.Close()

	e := apitest.New(t)
	svc := webhooks.New(webhooks.Options{Store: e.Store, Clock: e.Clock})
	ep := failingEndpoint(e, e.Acme, redirect.URL)
	_ = e.Webhooks.Publish(context.Background(), e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_4"})
	if n, _ := svc.RunDue(context.Background()); n != 1 {
		t.Fatalf("RunDue = %d", n)
	}
